declare const tools: { mcp__nexustrade__create_agent(args: {
  // READY chat-attachment ids from upload_chat_attachment. Bound onto the last user message as fileAttachments (same refs as the web FILES tab).
  attachment_ids?: Array<string>;
  // automated | semi-automated. When omitted, uses ChatSettings.agentAutomationMode.
  automationMode?: "automated" | "semi-automated";
  // Optional NexusGenAI conversation id
  conversationId?: string;
  // Caller-chosen token that makes this create retry-safe. Creation runs the router and the planner and regularly takes longer than the transport will wait, so a call that times out has usually SUCCEEDED. Pass a unique key, and if the call appears to fail, retry with the SAME key: you get the agent the first call created, never a second billed run. A key reused for a different prompt is rejected rather than silently replayed.
  idempotencyKey?: string;
  // Max agent iterations. When omitted, uses the user's saved ChatSettings.agentIterations (same as the web UI).
  maxIterations?: number;
  // ChatMessage array, e.g. [{"sender":"User","content":"..."}]
  messages?: Array<{
  // Message content
  content: string;
  // Optional message metadata
  data?: { [key: string]: unknown; };
  // Message sender, usually User
  sender: string;
  // Optional ISO timestamp
  timestamp?: string;
}>;
  // Deprecated compatibility field. Both values use Aurora's adaptive routing policy.
  session_depth?: "smart" | "deep";
  // Optional user-assigned display name for the new agent (max 100 chars). Enables later lookup via title on get_agent / send_agent_message / etc.
  title?: string;
}): Promise<CallToolResult>; };
