declare const tools: { mcp__nexustrade__query_backtest_events(args: {
  // Backtest ID (required). Obtained from backtest_portfolio results.
  backtest_id: string;
  // Collapse runs of consecutive identical NoSignal events into a single '… Nx NoSignal from T1 to T2' line. Default true. Turn off (false) if you need every heartbeat. Has no effect when include_condition_audit is true.
  collapse_repeats?: boolean;
  // ISO date filter end (e.g. 2024-12-31)
  end_date?: string;
  // Event types to include. Valid: Market, BuySignal, SellSignal, AlertSignal, LaunchAgentSignal, OpenOptionSignal, OptionResolutionAttempt, TradingAudit, CloseOptionSignal, RebalanceSignal, RebalanceOrder, InitiaiteDepositOrWithdraw, DepositAndWithdrawSignal, Transaction, Order, CopyTrading, Terminate, Deactivated, ApplyDividend, ApplyStockSplit, NoSignal, OrderGuard, OrderRejected, MarketClosed, PriceAnomaly, ReconcileStagePricing. Omit to get all actionable events (excludes Market, NoSignal, and OptionResolutionAttempt noise).
  event_types?: Array<string>;
  // Render per-condition audit on signal-bearing events (OpenOptionSignal, CloseOptionSignal, NoSignal, Buy/Sell/Alert/RebalanceSignal). Shows each base condition's lhsValue, comparison, rhsValue, and isTrue — the raw evaluation trace. Also disables NoSignal grouping (since each row may differ). Default false.
  include_condition_audit?: boolean;
  // Also include Market (price snapshots) and NoSignal (no-trigger heartbeats) events. Default false. Useful for debugging data feed timing or signal evaluation cadence.
  include_noise_events?: boolean;
  // For Order events only: filter by status (e.g. Filled, Accepted, Rejected)
  order_statuses?: Array<string>;
  // Page number (default 1)
  page?: number;
  // Results per page (default 20, max 50)
  page_size?: number;
  // Return the decoded event JSON verbatim instead of the summary formatter. Escape hatch when the formatter doesn't surface a field you need. Default false.
  raw?: boolean;
  // ISO date filter start (e.g. 2024-01-01)
  start_date?: string;
  // Filter to events from one strategy (Mongo ObjectId hex).
  strategy_id?: string;
  // Filter to events on one ticker (e.g. AVGO). Matches the denormalized ticker column on V2 events.
  ticker?: string;
}): Promise<CallToolResult>; };
