declare const tools: { mcp__nexustrade__systematic_sweep(args: {
  // Sweep end date (ISO format, e.g. 2024-12-31). Minute allows up to 730 days of minute data from start_date, counting minute-indicator warmup.
  end_date: string;
  // Optional fee contract keyed by AssetTypeEnum (Stock/Cryptocurrency/Option) with {amount, type: percent|dollars}. Omit for shared defaults matching standalone backtests (Option $0.65/contract). Unknown keys are rejected.
  fee_config?: { [key: string]: unknown; };
  // Optional metrics to persist on the optimizer; selection policy still controls sweep winner selection.
  fitness_functions?: Array<"sharpeRatio" | "sortinoRatio" | "winRate" | "profitFactor" | "calmarRatio" | "maxDrawdown" | "avgDrawdown" | "percentChange" | "dollarsSold" | "ulcerPerformanceIndex" | "participationRate" | "distinctUnderlyingsTraded" | "medianDeployment">;
  // Plain-English sweep gene intents (one string per variable gene axis). Each intent must vary a field over two or more candidate values. Never include fixed settings or instructions to keep an existing value; the seed portfolio already preserves them. The server compiles these via the Create Sweep Genes prompt into a validated SweepConfig with correct scope/field names (e.g. TakeProfitPct). Prefer this over hand-authoring sweep_config JSON. Call get_sweep_surface first to see applicable fields for the portfolio. Mutually exclusive with sweep_config.
  gene_intents?: Array<string>;
  // Time interval: Day or Minute (default Day; forced to Minute for intraday portfolios)
  interval?: "Day" | "Minute";
  // Number of best candidates to retain (default 25)
  leaderboard_size?: number;
  // Optional optimizer name
  name?: string;
  // Generational-search iteration count. Ignored for exhaustive mode except as an input to Auto when the grid is large.
  num_generations?: number;
  // Number of rolling training windows (default 3, max 20)
  num_windows?: number;
  // Candidates evaluated per generation in generational mode; also used as the worker chunk size for exhaustive mode.
  population_size?: number;
  // Portfolio ID (live, paper, or chat — from fetch_portfolios or create_portfolio). Server resolves the collection automatically.
  portfolio_id?: string;
  // When true, compile and validate the sweep plan without launching (returns plannedUnits, genes, warnings). Use before spending research tokens on a large grid.
  preview_only?: boolean;
  // Search mode. Auto runs exhaustive search when the gene grid is small enough and generational search when it is large. Do not repeatedly call the tool to simulate iterations.
  search_mode?: "Auto" | "Exhaustive" | "Generational";
  // Optional sweep winner selection policy (constrainedPrimary or pareto). Valid metrics: sharpeRatio, sortinoRatio, maxDrawdown, avgDrawdown, percentChange, dollarsSold, ulcerPerformanceIndex, participationRate, distinctUnderlyingsTraded, medianDeployment, winRate, profitFactor, calmarRatio. Constraints use `comparison` (e.g. medianDeployment greaterThanOrEqual 65 AND lessThanOrEqual 72 for a deployment band; participationRate greaterThanOrEqual 0.35). When primary is sortinoRatio, deployment targets must be constraints — medianDeployment as primary minimizes deployment. get_optimization_results returns medianDeployment on each row.
  selection_policy?: { [key: string]: unknown; };
  // Sweep start date (ISO format, e.g. 2024-01-01). Minute has ONE cap: 730 days of minute data, counting minute-indicator warmup. The 90-day first look is a default for callers who name no dates, not a ceiling — pass the window the question needs.
  start_date: string;
  // Advanced: full SweepConfig object. Prefer gene_intents for most workflows. Field names must match get_sweep_surface applicableFields (PascalCase, e.g. TakeProfitPct). Mutually exclusive with gene_intents.
  sweep_config?: { [key: string]: unknown; };
  // Deprecated training split ratio (0.75 style). Prefer training_percent.
  train_validation_ratio?: number;
  // Whole-percent share of the requested date range used for training; the remaining tail is validation (default 75). Uses app-style percent units, e.g. 75 not 0.75.
  training_percent?: number;
  // Whole-percent overlap between adjacent rolling training windows (default 50). Uses app-style percent units, e.g. 50 not 0.5.
  window_overlap_percent?: number;
}): Promise<CallToolResult>; };
```
